-- Will of the Void – database schema (PostgreSQL 16)
-- Each table declares its own foreign keys, so tables are created after the tables they
-- reference. The unique indexes at the end are game rules (unique names, one bonus,
-- no duplicate pairs), so they cannot be removed for performance reasons.
-- This file is also the Flyway migration api/src/main/resources/db/migration/V1__init.sql
-- 25 tables. Do not edit V1 after it has been applied: add a new V2__... migration.

CREATE TABLE "player" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "username" varchar(50) NOT NULL,
  "email" varchar(255) NOT NULL,
  "password_hash" varchar(255) NOT NULL,
  "role" varchar(10) NOT NULL CHECK (role IN ('USER', 'ADMIN')) DEFAULT 'USER',
  "email_verified_at" timestamptz,
  "defense_deck_id" bigint UNIQUE,
  "credit_balance" int NOT NULL CHECK (credit_balance >= 0) DEFAULT 0,
  "trophies" int NOT NULL CHECK (trophies >= 0) DEFAULT 0,
  "last_daily_bonus_at" timestamptz,
  "timezone" varchar(64) NOT NULL DEFAULT 'Europe/Rome',
  "protected_until" timestamptz,
  "invite_code" varchar(20) UNIQUE NOT NULL,
  "invited_by_id" bigint,
  "version" int NOT NULL DEFAULT 0,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "deleted_at" timestamptz,
  FOREIGN KEY ("invited_by_id") REFERENCES "player" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY IMMEDIATE
);

CREATE TABLE "player_token" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "player_id" bigint NOT NULL,
  "type" varchar(20) NOT NULL CHECK (type IN ('EMAIL_VERIFICATION', 'PASSWORD_RESET', 'REFRESH')),
  "token_hash" varchar(64) UNIQUE NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "expires_at" timestamptz NOT NULL,
  "used_at" timestamptz,
  CONSTRAINT "chk_token_expiry_after_creation" CHECK (expires_at > created_at),
  FOREIGN KEY ("player_id") REFERENCES "player" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE
);

CREATE TABLE "player_settings" (
  "player_id" bigint PRIMARY KEY,
  "reduce_motion" boolean NOT NULL DEFAULT false,
  "reduce_transparency" boolean NOT NULL DEFAULT false,
  "show_type_labels" boolean NOT NULL DEFAULT false,
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  FOREIGN KEY ("player_id") REFERENCES "player" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE
);

CREATE TABLE "deck" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "player_id" bigint NOT NULL,
  "name" varchar(100) NOT NULL,
  "status" varchar(12) NOT NULL CHECK (status IN ('INCOMPLETE', 'VALID', 'INVALID')) DEFAULT 'INCOMPLETE',
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  FOREIGN KEY ("player_id") REFERENCES "player" ("id") DEFERRABLE INITIALLY IMMEDIATE
);

-- player and deck reference each other (defense deck and owner), so this
-- foreign key can only be added once both tables exist.
ALTER TABLE "player" ADD FOREIGN KEY ("defense_deck_id") REFERENCES "deck" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY IMMEDIATE;

CREATE TABLE "faction" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(50) UNIQUE NOT NULL,
  "is_inert" boolean NOT NULL DEFAULT false
);

CREATE TABLE "faction_advantage" (
  "dominant_faction_id" int NOT NULL,
  "dominated_faction_id" int NOT NULL,
  "type" varchar(8) NOT NULL CHECK (type IN ('ATTACK', 'DEFENSE')),
  "value" int NOT NULL CHECK (value > 0) DEFAULT 2,
  CONSTRAINT "chk_advantage_different_factions" CHECK (dominant_faction_id <> dominated_faction_id),
  PRIMARY KEY ("dominant_faction_id", "dominated_faction_id"),
  FOREIGN KEY ("dominant_faction_id") REFERENCES "faction" ("id") DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY ("dominated_faction_id") REFERENCES "faction" ("id") DEFERRABLE INITIALLY IMMEDIATE
);

CREATE TABLE "rarity" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(50) UNIQUE NOT NULL,
  "sort_order" int UNIQUE NOT NULL,
  "total_points" int NOT NULL CHECK (total_points > 0),
  "max_copies_per_deck" int NOT NULL CHECK (max_copies_per_deck > 0),
  "max_per_deck" int CHECK (max_per_deck > 0),
  "duration_days" int CHECK (duration_days > 0),
  "is_tradeable" boolean NOT NULL DEFAULT true
);

CREATE TABLE "card" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(100) UNIQUE NOT NULL,
  "description" text,
  "image_url" varchar(255),
  "faction_id" int NOT NULL,
  "rarity_id" int NOT NULL,
  "attack" smallint NOT NULL CHECK (attack BETWEEN 1 AND 10),
  "defense" smallint NOT NULL CHECK (defense BETWEEN 1 AND 10),
  "is_active" boolean NOT NULL DEFAULT true,
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  FOREIGN KEY ("faction_id") REFERENCES "faction" ("id") DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY ("rarity_id") REFERENCES "rarity" ("id") DEFERRABLE INITIALLY IMMEDIATE
);

CREATE TABLE "collection_card" (
  "player_id" bigint NOT NULL,
  "card_id" bigint NOT NULL,
  "quantity" int NOT NULL CHECK (quantity > 0),
  "acquired_at" timestamptz NOT NULL DEFAULT (now()),
  "expires_at" timestamptz,
  CONSTRAINT "chk_wanderer_single_copy" CHECK (expires_at IS NULL OR quantity = 1),
  CONSTRAINT "chk_wanderer_expiry_after_arrival" CHECK (expires_at IS NULL OR expires_at > acquired_at),
  PRIMARY KEY ("player_id", "card_id"),
  FOREIGN KEY ("player_id") REFERENCES "player" ("id") DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY ("card_id") REFERENCES "card" ("id") DEFERRABLE INITIALLY IMMEDIATE
);

CREATE TABLE "memory_archive" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "player_id" bigint NOT NULL,
  "card_id" bigint NOT NULL,
  "arrived_at" timestamptz NOT NULL,
  "departed_at" timestamptz NOT NULL,
  FOREIGN KEY ("player_id") REFERENCES "player" ("id") DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY ("card_id") REFERENCES "card" ("id") DEFERRABLE INITIALLY IMMEDIATE
);

CREATE TABLE "deck_card" (
  "deck_id" bigint NOT NULL,
  "card_id" bigint NOT NULL,
  "quantity" int NOT NULL CHECK (quantity > 0),
  PRIMARY KEY ("deck_id", "card_id"),
  FOREIGN KEY ("deck_id") REFERENCES "deck" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY ("card_id") REFERENCES "card" ("id") DEFERRABLE INITIALLY IMMEDIATE
);

CREATE TABLE "starter_deck_card" (
  "card_id" bigint PRIMARY KEY,
  "quantity" int NOT NULL CHECK (quantity > 0),
  FOREIGN KEY ("card_id") REFERENCES "card" ("id") DEFERRABLE INITIALLY IMMEDIATE
);

CREATE TABLE "pack_type" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(100) NOT NULL,
  "credit_cost" int NOT NULL CHECK (credit_cost > 0),
  "is_active" boolean NOT NULL DEFAULT true,
  "available_from" timestamptz,
  "available_until" timestamptz,
  CONSTRAINT "chk_pack_availability_window" CHECK (available_from IS NULL OR available_until IS NULL OR available_until > available_from)
);

CREATE TABLE "pack_slot" (
  "pack_type_id" int NOT NULL,
  "position" smallint NOT NULL,
  "rarity_id" int NOT NULL,
  "card_count" int NOT NULL CHECK (card_count > 0),
  "upgrade_rarity_id" int,
  "upgrade_chance" numeric(5,2) CHECK (upgrade_chance > 0 AND upgrade_chance <= 100),
  CONSTRAINT "chk_slot_upgrade_complete" CHECK ((upgrade_rarity_id IS NULL) = (upgrade_chance IS NULL)),
  CONSTRAINT "chk_slot_upgrade_different_rarity" CHECK (upgrade_rarity_id <> rarity_id),
  PRIMARY KEY ("pack_type_id", "position"),
  FOREIGN KEY ("pack_type_id") REFERENCES "pack_type" ("id") DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY ("rarity_id") REFERENCES "rarity" ("id") DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY ("upgrade_rarity_id") REFERENCES "rarity" ("id") DEFERRABLE INITIALLY IMMEDIATE
);

CREATE TABLE "pack_opening" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "player_id" bigint NOT NULL,
  "pack_type_id" int NOT NULL,
  "credits_spent" int NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  FOREIGN KEY ("player_id") REFERENCES "player" ("id") DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY ("pack_type_id") REFERENCES "pack_type" ("id") DEFERRABLE INITIALLY IMMEDIATE
);

CREATE TABLE "credit_transaction" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "player_id" bigint NOT NULL,
  "amount" int NOT NULL,
  "reason" varchar(30) NOT NULL CHECK (reason IN ('REGISTRATION_BONUS', 'DAILY_BONUS', 'INVITE_BONUS', 'PACK_PURCHASE')),
  "pack_opening_id" bigint UNIQUE,
  "invited_player_id" bigint UNIQUE,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "chk_credit_reason_consistent" CHECK ((reason = 'PACK_PURCHASE' AND pack_opening_id IS NOT NULL AND invited_player_id IS NULL AND amount < 0) OR (reason = 'INVITE_BONUS' AND invited_player_id IS NOT NULL AND pack_opening_id IS NULL AND amount > 0) OR (reason IN ('REGISTRATION_BONUS', 'DAILY_BONUS') AND pack_opening_id IS NULL AND invited_player_id IS NULL AND amount > 0)),
  FOREIGN KEY ("player_id") REFERENCES "player" ("id") DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY ("pack_opening_id") REFERENCES "pack_opening" ("id") DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY ("invited_player_id") REFERENCES "player" ("id") DEFERRABLE INITIALLY IMMEDIATE
);

CREATE TABLE "pack_opening_card" (
  "pack_opening_id" bigint NOT NULL,
  "card_id" bigint NOT NULL,
  "quantity" int NOT NULL CHECK (quantity > 0),
  PRIMARY KEY ("pack_opening_id", "card_id"),
  FOREIGN KEY ("pack_opening_id") REFERENCES "pack_opening" ("id") DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY ("card_id") REFERENCES "card" ("id") DEFERRABLE INITIALLY IMMEDIATE
);

CREATE TABLE "trade" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "proposer_id" bigint NOT NULL,
  "recipient_id" bigint NOT NULL,
  "status" varchar(10) NOT NULL CHECK (status IN ('PENDING', 'ACCEPTED', 'REJECTED', 'CANCELLED', 'EXPIRED', 'FAILED')) DEFAULT 'PENDING',
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "expires_at" timestamptz NOT NULL,
  "closed_at" timestamptz,
  CONSTRAINT "chk_trade_different_players" CHECK (proposer_id <> recipient_id),
  CONSTRAINT "chk_trade_closed_when_not_pending" CHECK ((status = 'PENDING') = (closed_at IS NULL)),
  FOREIGN KEY ("proposer_id") REFERENCES "player" ("id") DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY ("recipient_id") REFERENCES "player" ("id") DEFERRABLE INITIALLY IMMEDIATE
);

CREATE TABLE "trade_card" (
  "trade_id" bigint NOT NULL,
  "card_id" bigint NOT NULL,
  "side" varchar(8) NOT NULL CHECK (side IN ('OFFER', 'REQUEST')),
  "quantity" int NOT NULL CHECK (quantity > 0),
  PRIMARY KEY ("trade_id", "card_id", "side"),
  FOREIGN KEY ("trade_id") REFERENCES "trade" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY ("card_id") REFERENCES "card" ("id") DEFERRABLE INITIALLY IMMEDIATE
);

CREATE TABLE "battle" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "mode" varchar(8) NOT NULL CHECK (mode IN ('FRIEND', 'QUICK', 'RANKED')),
  "status" varchar(10) NOT NULL CHECK (status IN ('PENDING', 'REJECTED', 'EXPIRED', 'CANCELLED', 'PLAYED')),
  "challenger_id" bigint NOT NULL,
  "opponent_id" bigint NOT NULL,
  "challenger_deck_id" bigint,
  "opponent_deck_id" bigint,
  "seed" bigint,
  "outcome" varchar(16) CHECK (outcome IN ('CHALLENGER_WIN', 'OPPONENT_WIN', 'DRAW')),
  "challenger_energy" int CHECK (challenger_energy >= 0),
  "opponent_energy" int CHECK (opponent_energy >= 0),
  "challenger_trophies_delta" int,
  "opponent_trophies_delta" int,
  "decks_snapshot" jsonb,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "expires_at" timestamptz,
  "played_at" timestamptz,
  CONSTRAINT "chk_battle_different_players" CHECK (challenger_id <> opponent_id),
  CONSTRAINT "chk_battle_outcome_when_played" CHECK ((status = 'PLAYED') = (outcome IS NOT NULL)),
  CONSTRAINT "chk_battle_trophies_ranked_only" CHECK (mode = 'RANKED' OR (challenger_trophies_delta IS NULL AND opponent_trophies_delta IS NULL)),
  CONSTRAINT "chk_battle_expiry_friend_only" CHECK (mode = 'FRIEND' OR expires_at IS NULL),
  CONSTRAINT "chk_battle_pending_has_deck" CHECK (status <> 'PENDING' OR challenger_deck_id IS NOT NULL),
  FOREIGN KEY ("challenger_id") REFERENCES "player" ("id") DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY ("opponent_id") REFERENCES "player" ("id") DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY ("challenger_deck_id") REFERENCES "deck" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY ("opponent_deck_id") REFERENCES "deck" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY IMMEDIATE
);

CREATE TABLE "battle_log" (
  "battle_id" bigint PRIMARY KEY,
  "turn_log" jsonb NOT NULL,
  FOREIGN KEY ("battle_id") REFERENCES "battle" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE
);

CREATE TABLE "opponent_list" (
  "player_id" bigint NOT NULL,
  "mode" varchar(8) NOT NULL CHECK (mode IN ('QUICK', 'RANKED')),
  "generated_at" timestamptz NOT NULL,
  "last_refresh_at" timestamptz,
  PRIMARY KEY ("player_id", "mode"),
  FOREIGN KEY ("player_id") REFERENCES "player" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE
);

CREATE TABLE "opponent_list_entry" (
  "player_id" bigint NOT NULL,
  "mode" varchar(8) NOT NULL,
  "position" smallint NOT NULL CHECK (position BETWEEN 1 AND 5),
  "opponent_id" bigint NOT NULL,
  "trophies_at_generation" int NOT NULL,
  "battle_id" bigint UNIQUE,
  CONSTRAINT "chk_entry_not_self" CHECK (player_id <> opponent_id),
  PRIMARY KEY ("player_id", "mode", "position"),
  FOREIGN KEY ("player_id", "mode") REFERENCES "opponent_list" ("player_id", "mode") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY ("opponent_id") REFERENCES "player" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY ("battle_id") REFERENCES "battle" ("id") DEFERRABLE INITIALLY IMMEDIATE
);

CREATE TABLE "friendship" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "requester_id" bigint NOT NULL,
  "addressee_id" bigint NOT NULL,
  "status" varchar(10) NOT NULL CHECK (status IN ('PENDING', 'ACCEPTED')) DEFAULT 'PENDING',
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "accepted_at" timestamptz,
  CONSTRAINT "chk_friendship_different_players" CHECK (requester_id <> addressee_id),
  CONSTRAINT "chk_friendship_accepted_at" CHECK ((status = 'ACCEPTED') = (accepted_at IS NOT NULL)),
  FOREIGN KEY ("requester_id") REFERENCES "player" ("id") DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY ("addressee_id") REFERENCES "player" ("id") DEFERRABLE INITIALLY IMMEDIATE
);

CREATE TABLE "notification" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "player_id" bigint NOT NULL,
  "type" varchar(30) NOT NULL CHECK (type IN ('ATTACK_RECEIVED', 'TRADE_RECEIVED', 'TRADE_ACCEPTED', 'TRADE_REJECTED', 'TRADE_CANCELLED', 'TRADE_EXPIRED', 'TRADE_FAILED', 'WANDERER_DEPARTED', 'DECK_INVALID', 'INVITE_BONUS', 'FRIEND_REQUEST_RECEIVED', 'FRIEND_REQUEST_ACCEPTED')),
  "battle_id" bigint,
  "trade_id" bigint,
  "card_id" bigint,
  "friendship_id" bigint,
  "is_read" boolean NOT NULL DEFAULT false,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  FOREIGN KEY ("player_id") REFERENCES "player" ("id") DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY ("battle_id") REFERENCES "battle" ("id") DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY ("trade_id") REFERENCES "trade" ("id") DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY ("card_id") REFERENCES "card" ("id") DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY ("friendship_id") REFERENCES "friendship" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE
);

CREATE UNIQUE INDEX "uq_player_username_lower" ON "player" ((lower(username)));

CREATE UNIQUE INDEX "uq_player_email_lower" ON "player" ((lower(email)));

CREATE UNIQUE INDEX "uq_deck_player_name" ON "deck" ("player_id", "name");

CREATE UNIQUE INDEX "uq_faction_advantage_pair" ON "faction_advantage" ((LEAST(dominant_faction_id, dominated_faction_id)), (GREATEST(dominant_faction_id, dominated_faction_id)));

CREATE UNIQUE INDEX "uq_opponent_list_entry_opponent" ON "opponent_list_entry" ("player_id", "mode", "opponent_id");

-- One registration bonus per player
CREATE UNIQUE INDEX "uq_credit_registration_bonus" ON "credit_transaction" ("player_id") WHERE reason = 'REGISTRATION_BONUS';

CREATE UNIQUE INDEX "uq_friendship_pair" ON "friendship" ((LEAST(requester_id, addressee_id)), (GREATEST(requester_id, addressee_id)));
